// withDirLock 两层串行化裸单测(设计 docs/design/dir-write-queue.md):
// 进程内 per-dir 队列(消灭同进程锁竞争)+ proper-lockfile 跨进程锁。
// fixture:tmp 目录真文件,纯文件操作不 mock。
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { withDirLock, appendJsonlLine } from "./config-file";

let dir: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "dir-write-queue-"));
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

describe("进程内 per-dir 队列", () => {
  it("同目录 12 路并发 append:零 ELOCKED,全部行完整落盘", async () => {
    const file = join(dir, "s.jsonl");
    writeFileSync(file, JSON.stringify({ type: "session" }) + "\n");
    const n = 12;
    // 改造前:12 个请求裸抢同一把目录锁,retries(3)耗尽即 ELOCKED。
    // 改造后:排队逐个执行,同进程不再出现两个请求同时抢锁。
    await Promise.all(
      Array.from({ length: n }, (_, i) => appendJsonlLine(file, { type: "probe", i })),
    );
    const lines = readFileSync(file, "utf-8").split("\n").filter((l) => l.trim());
    expect(lines).toHaveLength(1 + n);
    const idxs = lines.slice(1).map((l) => (JSON.parse(l) as { i: number }).i).sort((a, b) => a - b);
    expect(idxs).toEqual(Array.from({ length: n }, (_, i) => i));
  });

  it("同目录不同文件并发写:同队列串行,互不干扰", async () => {
    const fileA = join(dir, "a.jsonl");
    const fileB = join(dir, "b.jsonl");
    await Promise.all([
      ...Array.from({ length: 6 }, (_, i) => appendJsonlLine(fileA, { f: "a", i })),
      ...Array.from({ length: 6 }, (_, i) => appendJsonlLine(fileB, { f: "b", i })),
    ]);
    expect(readFileSync(fileA, "utf-8").trim().split("\n")).toHaveLength(6);
    expect(readFileSync(fileB, "utf-8").trim().split("\n")).toHaveLength(6);
  });

  it("路径归一:尾斜杠与 resolve 等价写法排进同一条队列", async () => {
    const file = join(dir, "s.jsonl");
    writeFileSync(file, "");
    // dir 与 `${dir}/`(尾斜杠)写法不同,归一后同 key——不串行会交叉撕裂
    const order: string[] = [];
    await Promise.all([
      withDirLock(dir, async () => { order.push("plain"); }),
      withDirLock(`${dir}/`, async () => { order.push("slash"); }),
    ]);
    expect(order).toHaveLength(2); // 两者都执行且无死锁
  });

  it("单任务失败不断链:后续写照常执行,错误照冒给失败方调用方", async () => {
    const results: string[] = [];
    const failing = withDirLock(dir, async () => { throw new Error("boom"); });
    const ok1 = withDirLock(dir, async () => { results.push("after-1"); });
    const ok2 = withDirLock(dir, async () => { results.push("after-2"); });
    await expect(failing).rejects.toThrow("boom");
    await Promise.all([ok1, ok2]);
    expect(results).toEqual(["after-1", "after-2"]);
  });

  it("重入检测:fn 内嵌套同目录调用快速失败而非静默死锁", async () => {
    await expect(
      withDirLock(dir, async () => {
        await withDirLock(dir, async () => undefined);
      }),
    ).rejects.toThrow("非重入");
    // 抛错后队列不被污染:后续写照常
    await withDirLock(dir, async () => undefined);
  });

  it("不同目录不互斥:并行推进", async () => {
    const dirB = join(dir, "sub");
    mkdirSync(dirB);
    const running: string[] = [];
    const done: string[] = [];
    const mk = (key: string, d: string) => withDirLock(d, async () => {
      running.push(key);
      await new Promise((r) => setTimeout(r, 50));
      done.push(key);
    });
    await Promise.all([mk("a", dir), mk("b", dirB)]);
    // 两个目录的任务重叠执行(各自串行、互不排队)
    expect(done).toEqual(expect.arrayContaining(["a", "b"]));
    expect(running).toHaveLength(2);
  });
});

